-- SMO catalog import generated from smo-supplies-list.pdf
-- Legacy bootstrap import for databases that have not yet run migration
-- 2026_10_19_021000_normalize_supply_options. Do not rerun this file after
-- that migration; manage the normalized catalog through the application.
-- Opening quantities and reorder thresholds are planning defaults for initial setup.
-- Reconcile quantity against a signed physical count before production use, then
-- review min_stock_level periodically against actual consumption and lead time.
-- unit_price contains a reference price per listed unit, not a supplier quotation.
-- Common-use item prices follow the PS-PhilGEPS catalogue dated 2026-10-16;
-- unmatched branded/legacy items use conservative Philippine retail estimates.
-- When an item has size or brand choices, unit_price is the baseline variant price.
-- Price references (review before each procurement cycle):
-- https://sys.ps-philgeps.gov.ph/catalogue/cse-list
-- https://www.dti.gov.ph/wp-content/uploads/2025/08/BNPCSRPBULLETIN01FEBRUARY2025.002.pdf
-- The retired HDMI category is mapped to Office Supplies to match the current application schema.
-- Names for codes 104-00023 and 104-00031 were restored from their catalog sequence because the PDF omitted their visible name text.
-- Product names describe the item itself. Brand, color, size, style, and similar
-- purchasing choices belong in configurable_options instead of item_name.
-- SMO stock codes are retained in specifications; model_number is reserved for
-- actual manufacturer model numbers.

USE `defaultdb`;

START TRANSACTION;

ON DUPLICATE KEY UPDATE updated_at = VALUES(updated_at);

ON DUPLICATE KEY UPDATE
  supply_category_id = VALUES(supply_category_id),
  quantity = IF(quantity = 0, VALUES(quantity), quantity),
  brand = VALUES(brand),
  model_number = VALUES(model_number),
  requisition_tier = VALUES(requisition_tier),
  specifications = VALUES(specifications),
  configurable_options = VALUES(configurable_options),
  unit = VALUES(unit),
  unit_price = VALUES(unit_price),
  min_stock_level = VALUES(min_stock_level),
  updated_at = NOW();

COMMIT;
